const raw = $input.first().json;
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') { data = rawBody; }
}

const task_id    = data.task_id    || 'unknown';
const language   = data.language   || 'javascript';
const zipBase64  = data.existing_zip_base64 || null;
const prompt     = data.improve_prompt || data.userRequest || '';

if (!zipBase64) {
  return [{ json: { task_id, language, prompt, improve_mode: false, existing_code: null,
    existing_routes: [], existing_stores: {}, existing_data_model: {}, existing_version: null,
    changelog_context: '', files_found: [] } }];
}

let existingFiles = {};
let existingServerJs = '';
let existingAppJs = '';

try {
  // Décoder le ZIP en binaire (gérer le préfixe data URL si présent)
  let base64Clean = zipBase64;
  if (typeof base64Clean === 'string' && base64Clean.indexOf(',') > 0 && base64Clean.indexOf('base64') > 0) {
    base64Clean = base64Clean.split(',')[1];
  }
  const buf = Buffer.from(base64Clean, 'base64');
  const str = buf.toString('binary');

  // Chercher les fichiers dans le ZIP par signature PK\x03\x04
  const fileMarkers = ['server.js', 'frontend/app.js', 'frontend/index.html', 'README.md', 'package.json'];

  fileMarkers.forEach(marker => {
    // Chercher le nom du fichier dans le binaire
    const idx = str.indexOf(marker);
    if (idx < 0) return;

    // Lire la taille du fichier depuis le header ZIP (offset 18 = taille compressée)
    // Le nom du fichier commence à offset 30 dans le local file header
    // Chercher le header PK\x03\x04 avant le nom du fichier
    let headerIdx = idx - 30;
    // Chercher en arrière le header signature
    for (let i = idx; i >= Math.max(0, idx - 50); i--) {
      if (str.charCodeAt(i) === 0x50 && str.charCodeAt(i+1) === 0x4B &&
          str.charCodeAt(i+2) === 0x03 && str.charCodeAt(i+3) === 0x04) {
        headerIdx = i;
        break;
      }
    }

    // Lire la taille depuis offset 18 (little-endian uint32)
    const sizeOffset = headerIdx + 18;
    const size = str.charCodeAt(sizeOffset) |
                 (str.charCodeAt(sizeOffset+1) << 8) |
                 (str.charCodeAt(sizeOffset+2) << 16) |
                 (str.charCodeAt(sizeOffset+3) << 24);

    // Lire la longueur du nom de fichier (offset 26)
    const nameLen = str.charCodeAt(headerIdx+26) | (str.charCodeAt(headerIdx+27) << 8);
    const extraLen = str.charCodeAt(headerIdx+28) | (str.charCodeAt(headerIdx+29) << 8);

    // Le contenu commence après le header
    const contentStart = headerIdx + 30 + nameLen + extraLen;
    const contentEnd = contentStart + Math.min(size, 30000);

    if (size > 0 && size < 100000 && contentEnd <= str.length) {
      try {
        const rawContent = str.substring(contentStart, contentEnd);
        const content = Buffer.from(rawContent, 'binary').toString('utf8');
        // Vérifier que le contenu est lisible (texte valide)
        if (content.length > 10) {
          existingFiles[marker] = content;
        }
      } catch(e) {}
    }
  });
} catch(e) {
  console.log('Erreur extraction ZIP:', e.message);
}

// Analyser server.js
let existingRoutes = [];
let existingStores = {};
let projectName = 'Application';
let existingVersion = '1.0';

existingServerJs = existingFiles['server.js'] || '';
existingAppJs    = existingFiles['frontend/app.js'] || '';

if (existingServerJs) {
  // Extraire les routes avec regex robuste
  const routePattern = /app\.(get|post|put|patch|delete)\s*\(\s*['"`]([^'"`]+)['"`]/gi;
  let match;
  while ((match = routePattern.exec(existingServerJs)) !== null) {
    existingRoutes.push({ method: match[1].toUpperCase(), path: match[2] });
  }

  // Extraire les stores
  const storePattern = /const\s+(store_(\w+))\s*=/gi;
  while ((match = storePattern.exec(existingServerJs)) !== null) {
    const storeName = match[2];
    existingStores[storeName] = { store_name: storeName, required_fields: [] };
  }

  // Extraire les required_fields pour chaque POST
  existingRoutes.filter(r => r.method === 'POST').forEach(route => {
    const seg = route.path.replace(/^\//, '').split('/')[0];
    const fieldPattern = new RegExp('app\\.post\\s*\\(\\s*[\'"`]' + seg.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[\'"`].*?const\\s*\\{([^}]+)\\}\\s*=\\s*req\\.body', 'si');
    const fieldMatch = existingServerJs.match(fieldPattern);
    if (fieldMatch) {
      const fields = fieldMatch[1].split(',').map(f => f.trim()).filter(Boolean);
      if (existingStores[seg]) {
        existingStores[seg].required_fields = fields;
      } else {
        const resName = seg.replace(/s$/, '');
        existingStores[resName] = { store_name: seg, required_fields: fields };
      }
    }
  });
}

// Extraire nom projet et version depuis README + package.json
const readme = existingFiles['README.md'] || '';
const pkgRaw = existingFiles['package.json'] || '';

if (readme) {
  const titleMatch = readme.match(/^#\s+(.+)/m);
  if (titleMatch) projectName = titleMatch[1].trim().split(' ')[0]; // Premier mot seulement
}

// Version depuis package.json (source de vérité)
if (pkgRaw) {
  const pkgVersionMatch = pkgRaw.match(/"version"\s*:\s*"(\d+\.\d+)/);
  if (pkgVersionMatch) existingVersion = pkgVersionMatch[1];
}
// Fallback README : chercher explicitement "Version actuelle" ou titre "# Nom v1.x"
if (existingVersion === '1.0' && readme) {
  const titleVersion = readme.match(/^#\s+\S+\s+v(\d+\.\d+)/m);
  if (titleVersion) existingVersion = titleVersion[1];
  else {
    // Chercher "Version actuelle : 1.x" (pas dans roadmap)
    const curVersion = readme.match(/[Vv]ersion\s+actuelle\s*:?\s*(\d+\.\d+)/);
    if (curVersion) existingVersion = curVersion[1];
  }
}

// Calculer prochaine version
const [major, minor] = existingVersion.split('.').map(Number);
const pl = prompt.toLowerCase();
const isMajor = pl.includes('base de donn') || pl.includes('authentification') || pl.includes('auth');
const nextVersion = isMajor ? (major + 1) + '.0' : major + '.' + (minor + 1);

// Résumé routes pour le contexte
const routesSummary = existingRoutes.map(r => r.method + ' ' + r.path).join(', ');
const storesSummary = Object.keys(existingStores).join(', ');

const changelogContext = 'PROJET EXISTANT : ' + projectName + ' v' + existingVersion + '\n' +
  'PROCHAINE VERSION : v' + nextVersion + '\n' +
  'ROUTES EXISTANTES : ' + (routesSummary || 'aucune') + '\n' +
  'STORES EXISTANTS : ' + (storesSummary || 'aucun') + '\n\n' +
  'CODE SERVER.JS EXISTANT :\n' + existingServerJs.substring(0, 2000);

return [{
  json: {
    task_id, language, prompt,
    improve_mode:       true,
    project_name:       projectName,
    existing_version:   existingVersion,
    next_version:       nextVersion,
    existing_routes:    existingRoutes,
    existing_stores:    existingStores,
    existing_server_js: existingServerJs.substring(0, 3000),
    existing_app_js:    existingAppJs.substring(0, 2000),
    changelog_context:  changelogContext,
    files_found:        Object.keys(existingFiles)
  }
}];
